    let value = flow.get(key);
    result[key] = value;
}

// Output ke debug
msg.payload = result;
return msg;

function encodeForm(obj) {
    return Object.keys(obj)
        .map(k => encodeURIComponent(k) + "=" + encodeURIComponent(obj[k]))
        .join("&");
}

